import { readFile, writeFile } from "node:fs/promises";
import { fileURLToPath } from "node:url";
import { createRequire } from "node:module";
import postcss from "postcss";
import tailwind from "tailwindcss-v3";
import prefixSelector from "postcss-prefix-selector";

const root = fileURLToPath(new URL("../../", import.meta.url));
const require = createRequire(import.meta.url);
const sourceConfig = require("../../tailwind.config.cjs");
const scope = ".cc-switch-web";
const compiled = await postcss([tailwind({
  ...sourceConfig,
  content: [{ raw: await readFile(new URL("../index.html", import.meta.url), "utf8"), extension: "html" }, `${root}/src/**/*.{ts,tsx}`, `${root}/../openhands-extensions/src/**/*.{ts,tsx}`],
})]).process(await readFile(new URL("../index.css", import.meta.url), "utf8"), { from: `${root}/src/index.css`, map: false });

// Tailwind 3's preflight, tokens and utilities are confined to this surface;
// the host's Tailwind 4 theme/reset and animation names are never replaced.
const names = new Map();
compiled.root.walkAtRules(/keyframes$/, rule => {
  const name = rule.params.trim();
  names.set(name, `cc-switch-${name}`);
  rule.params = names.get(name);
});
compiled.root.walkDecls(declaration => {
  if (declaration.prop !== "animation" && declaration.prop !== "animation-name") return;
  declaration.value = declaration.value.replace(/[a-zA-Z_][\w-]*/g, token => names.get(token) ?? token);
});
const isolated = await postcss([prefixSelector({
  prefix: scope,
  transform(prefix, selector, prefixed) {
    if (selector === ":root" || selector === "html" || selector === "body") return scope;
    if (selector === ".dark" || selector === "html.dark") return `.dark ${scope}`;
    if (selector.startsWith(".dark ")) return `.dark ${scope} ${selector.slice(6)}`;
    if (selector.startsWith("html")) return selector.replace(/^html([^ ]*)\s*/, `html$1 ${scope} `);
    return prefixed;
  },
})]).process(compiled.root.toString(), { from: undefined, map: false });
await writeFile(new URL("./management.css", import.meta.url), `/* Generated by @pm/cc-switch-ui build:css from the pinned source index.css + tailwind.config.cjs. */\n${isolated.css}\n`);
